INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING', 'SCIE.G5.MATTER.MIXTURES.SEPARATION_METHOD_CHOICE', 'skill', 'essential', 'Passing water through ash and filtering is a separation method (Science Grade 5). Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION.M_AG7_SP_GOOD', 'AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION', 'Thinks more fertiliser always makes soil healthier, so adds far more than the packet says.', '{"question":"What can too much fertiliser do to the soil?","wrong_answer":"Make it healthier","correct_answer":"Pollute and harm it"}'::jsonb, 'The child knows fertiliser feeds crops and reasons that more food is always better.', 'Offer "Make it healthier" next to the right answer and ask the question again in a new situation.', 'Show the packet rate (a bottle top per hole); explain that the extra salts burn roots and wash into rivers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION.M_AG7_SP_PLASTIC', 'AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION', 'Thinks polythene buried in the soil rots and feeds plants like leaves do.', '{"question":"Why is polythene a problem in the soil?","wrong_answer":"It feeds the plants","correct_answer":"It does not rot and blocks water"}'::jsonb, 'The child has seen leaves and peelings disappear in soil and expects all waste to rot.', 'Offer "It feeds the plants" next to the right answer and ask the question again in a new situation.', 'Dig up a polythene bag buried last term next to a buried leaf; one is unchanged.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION.M_AG7_SP_CONTROL', 'AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION', 'Names burning plastic as a way to control soil pollution.', '{"question":"Which helps to control soil pollution?","wrong_answer":"Burning plastic on the farm","correct_answer":"Reducing and recycling waste"}'::jsonb, 'Burning makes the rubbish disappear from sight, so the child thinks the problem is gone.', 'Offer "Burning plastic on the farm" next to the right answer and ask the question again in a new situation.', 'Ask where the smoke, ash and melted plastic go; burning moves the pollution into the air and soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION.M_AG7_SP_CONTAINER', 'AGRI.G7.CONSER.CONTROLLING_SOIL_POLLUTI.SOIL_POLLUTION', 'Reuses empty pesticide containers to store water or food.', '{"question":"What should be done with an empty pesticide container?","wrong_answer":"Wash it and use it for drinking water","correct_answer":"Return it to the seller or dispose of it as the label says; never reuse it"}'::jsonb, 'The containers look strong and useful, and the child does not know washing leaves poison behind.', 'Offer "Wash it and use it for drinking water" next to the right answer and ask the question again in a new context.', 'Read a pesticide label''s disposal instructions with the class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF.M_AG7_RO_WASTE', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF', 'Thinks surface run-off is only waste water to be got rid of.', '{"question":"What can be done with surface run-off?","wrong_answer":"Nothing, it is useless","correct_answer":"Trap it and use it in the garden"}'::jsonb, 'The child sees run-off flooding paths and roads and only as a nuisance.', 'Offer "Nothing, it is useless" next to the right answer and ask the question again in a new situation.', 'Follow run-off after rain to a low place where plants grow green; ask what it could water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF.M_AG7_RO_STRUCTURE', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF', 'Names a bare path or open ground as a structure that traps run-off.', '{"question":"Which traps run-off?","wrong_answer":"A bare path","correct_answer":"A trench or a water pan"}'::jsonb, 'The child thinks any place water flows over is a structure for it.', 'Offer "A bare path" next to the right answer and ask the question again in a new situation.', 'Compare water poured on a bare tray and on a tray with a small ditch dug across it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF.M_AG7_RO_MULCH', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF', 'Thinks mulch makes run-off flow faster.', '{"question":"What does mulch do to run-off?","wrong_answer":"Speeds it up","correct_answer":"Slows it down"}'::jsonb, 'The child thinks a cover makes the surface slippery like a plastic sheet.', 'Offer "Speeds it up" next to the right answer and ask the question again in a new situation.', 'Pour water on a tilted bare tray and a mulched tray; time how fast it runs off each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF.M_AG7_RO_ROOF', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RUNOFF', 'Does not count water from roofs and paved areas as run-off that can be used.', '{"question":"Which water can be led into a retention pit?","wrong_answer":"Only rain falling straight into the pit","correct_answer":"Run-off from roofs, paths and slopes as well"}'::jsonb, 'The child thinks only water that falls on the garden can be used there.', 'Offer "Only rain falling straight into the pit" next to the right answer and ask the question again in a new context.', 'Trace where the roof water goes after a storm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD.M_AG7_RB_DOWN', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD', 'Digs the ditch straight down the slope.', '{"question":"How is a retention ditch laid out on a slope?","wrong_answer":"Straight down the slope","correct_answer":"Across the slope, along the contour"}'::jsonb, 'The child digs where the water runs, thinking the ditch should follow it.', 'Offer "Straight down the slope" next to the right answer and ask the question again in a new context.', 'Pour water down a tray with a ditch down the slope and one across it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD.M_AG7_RB_BANK', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD', 'Throws the dug soil on the uphill side.', '{"question":"Where is the dug soil put when making a retention ditch?","wrong_answer":"On the uphill side","correct_answer":"On the downhill side as a bank"}'::jsonb, 'The child does not picture the bank as a wall that holds water.', 'Offer "On the uphill side" next to the right answer and ask the question again in a new context.', 'Model both on a tray; see which holds the water in the ditch.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD.M_AG7_RB_CROP', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD', 'Plants maize or beans in the wet retention pit.', '{"question":"Which crop suits a retention pit that stays wet?","wrong_answer":"Maize or beans","correct_answer":"Bananas, arrowroots, sugarcane or napier grass"}'::jsonb, 'The child plants the usual field crops.', 'Offer "Maize or beans" next to the right answer and ask the question again in a new context.', 'Ask which crops grow in wet valley bottoms.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD.M_AG7_RB_SILT', 'AGRI.G7.CONSER.CONSTRUCTING_WATER_RETEN.RETENTION_BUILD', 'Thinks a retention ditch needs no care once dug.', '{"question":"Why must a retention ditch be cleared after heavy rain?","wrong_answer":"It does not need clearing","correct_answer":"Silt fills it and it stops holding water"}'::jsonb, 'The child thinks digging is the whole job.', 'Offer "It does not need clearing" next to the right answer and ask the question again in a new context.', 'Show a ditch half filled with silt after a season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP.M_AG7_NK_LONG', 'AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP', 'Thinks boiling vegetables for a long time keeps them nutritious and safe.', '{"question":"How should vegetables be cooked to keep vitamins?","wrong_answer":"Boil them for a long time","correct_answer":"Cook them a short time with a lid"}'::jsonb, 'The child links long cooking with safety and softness.', 'Offer "Boil them for a long time" next to the right answer and ask the question again in a new situation.', 'Compare bright green kale cooked for 5 minutes with grey kale boiled for 40.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP.M_AG7_NK_WATER', 'AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP', 'Throws away the water vegetables were cooked in.', '{"question":"What should be done with the cooking water?","wrong_answer":"Throw it away at once","correct_answer":"Use it, for example in soup"}'::jsonb, 'The child sees the cooking water as dirty, not as holding minerals and vitamins.', 'Offer "Throw it away at once" next to the right answer and ask the question again in a new situation.', 'Show the green colour in the water; explain some vitamins and minerals leave the leaves into it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP.M_AG7_NK_WASH', 'AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP', 'Cuts vegetables up small before washing them.', '{"question":"When should vegetables be washed?","wrong_answer":"After they are cut up small","correct_answer":"Before they are cut"}'::jsonb, 'The child thinks small pieces wash cleaner.', 'Offer "After they are cut up small" next to the right answer and ask the question again in a new situation.', 'Explain that vitamins wash out of the cut surfaces; wash whole leaves first, then cut.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP.M_AG7_NK_EARLY', 'AGRI.G7.CONSER.CONSERVING_FOOD_NUTRIENT.NUTRIENT_KEEP', 'Cuts vegetables hours before cooking and leaves them in the open or in water.', '{"question":"When should vegetables be cut for cooking?","wrong_answer":"Hours before, and left to soak","correct_answer":"Just before cooking"}'::jsonb, 'The child thinks preparing early saves time with no loss.', 'Offer "Hours before, and left to soak" next to the right answer and ask the question again in a new context.', 'Leave cut kale out for three hours: it wilts and darkens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE.M_AG7_TI_DRY', 'AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE', 'Thinks trees dry up the land by drinking all the water.', '{"question":"What do trees do to the land?","wrong_answer":"Dry it up","correct_answer":"Help hold the soil and bring rain"}'::jsonb, 'The child has heard that some trees (like eucalyptus) use much water and applies it to all trees.', 'Offer "Dry it up" next to the right answer and ask the question again in a new situation.', 'Compare the soil under a tree''s shade with bare ground at midday; talk about cover, humus and springs in forests.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE.M_AG7_TI_GAS', 'AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE', 'Says trees give out smoke or carbon dioxide instead of oxygen.', '{"question":"Which gas do trees give out?","wrong_answer":"Smoke","correct_answer":"Oxygen"}'::jsonb, 'The child links trees with firewood and smoke.', 'Offer "Smoke" next to the right answer and ask the question again in a new situation.', 'Recall air components from Science: plants take in carbon dioxide and give out oxygen in daylight.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE.M_AG7_TI_USE', 'AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE', 'Thinks trees are useful only as firewood.', '{"question":"What else do trees give?","wrong_answer":"Only firewood","correct_answer":"Shade, fruit, timber and shelter"}'::jsonb, 'At home the child sees trees cut mainly for fuel.', 'Offer "Only firewood" next to the right answer and ask the question again in a new situation.', 'List what a mango or grevillea gives over its life: fruit, shade, timber, fodder, bees, windbreak.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE.M_AG7_TI_RAIN', 'AGRI.G7.CONSER.GROWING_TREES.TREES_IMPORTANCE', 'Thinks trees have nothing to do with rain or water in rivers.', '{"question":"How do forests help rivers like the Tana?","wrong_answer":"They do not; rivers come from the sea","correct_answer":"They hold rain in the soil and release it slowly into streams and springs"}'::jsonb, 'The child does not connect forests in water towers with the rivers below.', 'Offer "They do not; rivers come from the sea" next to the right answer and ask the question again in a new context.', 'Show the Mau or Mount Kenya forests on a map and the rivers flowing out of them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING.M_AG7_TP_SLEEVE', 'AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING', 'Plants the seedling with its polythene sleeve still on.', '{"question":"What is done with the seedling''s polythene sleeve when planting?","wrong_answer":"Leave it on to protect the roots","correct_answer":"Remove it carefully without breaking the soil ball"}'::jsonb, 'The child thinks the sleeve is part of the plant''s home.', 'Offer "Leave it on to protect the roots" next to the right answer and ask the question again in a new context.', 'Show roots curled inside a sleeve dug up after a year.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING.M_AG7_TP_SITE', 'AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING', 'Plants a tree right next to a house, under power lines or over a pit latrine.', '{"question":"Where should a tree that grows big be planted?","wrong_answer":"Right next to the house wall","correct_answer":"Away from buildings, power lines and latrines, with room to grow"}'::jsonb, 'The child thinks of the small seedling, not the full-grown tree.', 'Offer "Right next to the house wall" next to the right answer and ask the question again in a new context.', 'Show a tree whose roots have cracked a wall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING.M_AG7_TP_ONCE', 'AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING', 'Waters the tree only on planting day.', '{"question":"How long must a newly planted tree be cared for?","wrong_answer":"Only on the day it is planted","correct_answer":"Until it is established: watered, weeded and protected for months"}'::jsonb, 'The child thinks planting is the job.', 'Offer "Only on the day it is planted" next to the right answer and ask the question again in a new context.', 'Show a care record and seedlings that died after planting day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING.M_AG7_TP_TYPE', 'AGRI.G7.CONSER.GROWING_TREES.TREE_PLANTING', 'Thinks any tree can be planted anywhere, such as eucalyptus beside a spring or a wetland.', '{"question":"Why is eucalyptus not planted beside springs and wetlands?","wrong_answer":"It does not matter which tree","correct_answer":"It uses a lot of water and can dry the spring"}'::jsonb, 'The child sees all trees as equally good for the land.', 'Offer "It does not matter which tree" next to the right answer and ask the question again in a new context.', 'Ask the class which indigenous trees grow by rivers in their area.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH.M_AG7_TL_SMALL', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH', 'Gives a coarse tilth for small seeds such as carrots.', '{"question":"Which tilth suits small seeds like carrot?","wrong_answer":"Coarse tilth","correct_answer":"Fine tilth"}'::jsonb, 'The child thinks a rough bed is less work and that seeds find their way.', 'Offer "Coarse tilth" next to the right answer and ask the question again in a new situation.', 'Sow carrot seed on a lumpy tray and a fine tray; count how many come up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH.M_AG7_TL_TUBER', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH', 'Gives a fine tilth for sweet potato vines and tubers.', '{"question":"Which tilth suits sweet potato cuttings?","wrong_answer":"Fine tilth","correct_answer":"Coarse tilth"}'::jsonb, 'The child thinks finer is always better for every crop.', 'Offer "Fine tilth" next to the right answer and ask the question again in a new situation.', 'Explain that big planting materials need air and loose clods; fine soil packs hard round them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH.M_AG7_TL_MEDIUM', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH', 'Gives a fine tilth for maize and beans.', '{"question":"Which tilth suits maize and beans?","wrong_answer":"Fine tilth","correct_answer":"Medium tilth"}'::jsonb, 'The child sorts seeds into tiny and big only, with no middle.', 'Offer "Fine tilth" next to the right answer and ask the question again in a new situation.', 'Lay carrot, bean and potato side by side: small, medium, large match fine, medium, coarse.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH.M_AG7_TL_MEANING', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH', 'Thinks tilth means how fertile the soil is.', '{"question":"What is tilth?","wrong_answer":"How fertile the soil is","correct_answer":"How fine or coarse the soil is after it is dug"}'::jsonb, 'The child links soil words with fertility.', 'Offer "How fertile the soil is" next to the right answer and ask the question again in a new context.', 'Show three trays of the same soil dug to different sizes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP.M_AG7_TP_RAKE', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP', 'Thinks raking is the first step in preparing a seedbed.', '{"question":"Which is done first when preparing a seedbed?","wrong_answer":"Raking","correct_answer":"Clearing the site and digging"}'::jsonb, 'The child has seen the raking at the end and thinks it starts the job.', 'Offer "Raking" next to the right answer and ask the question again in a new context.', 'Try to rake a hard, uncleared plot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP.M_AG7_TP_WET', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP', 'Digs when the soil is soaking wet.', '{"question":"When is the best time to dig a seedbed?","wrong_answer":"When the soil is soaking wet","correct_answer":"When the soil is moist but not wet"}'::jsonb, 'The child thinks wet soil is soft and easy.', 'Offer "When the soil is soaking wet" next to the right answer and ask the question again in a new context.', 'Dig a lump of soaked clay: it smears and dries into hard clods.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP.M_AG7_TP_ROOTS', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP', 'Leaves weed roots and couch grass in the seedbed.', '{"question":"Why are weed roots removed when preparing a seedbed?","wrong_answer":"They add manure","correct_answer":"They grow again and compete with the crop"}'::jsonb, 'The child thinks cut weeds are dead.', 'Offer "They add manure" next to the right answer and ask the question again in a new context.', 'Show couch grass roots sprouting from a small piece.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP.M_AG7_TP_TOOL', 'AGRI.G7.FOOD_P.CROP_ESTABLISHMENT.TILTH_PREP', 'Uses a rake to break hard ground for primary cultivation.', '{"question":"Which tool is used to dig hard ground first?","wrong_answer":"A rake","correct_answer":"A jembe or forked jembe"}'::jsonb, 'The child does not tell digging tools from finishing tools.', 'Offer "A rake" next to the right answer and ask the question again in a new context.', 'Show each tool and what it does to a lump of hard soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES.M_AG7_CP_WEED', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES', 'Thinks weeds help the crop grow by giving it company and shade.', '{"question":"Why is weeding done?","wrong_answer":"Weeds help the crop grow","correct_answer":"To remove competition for water and food"}'::jsonb, 'The child sees weeds as green plants like the crop and does not picture the roots competing.', 'Offer "Weeds help the crop grow" next to the right answer and ask the question again in a new situation.', 'Grow two rows of beans, one weeded; compare their size after three weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES.M_AG7_CP_THIN', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES', 'Says thinning is replacing seeds that failed to come up.', '{"question":"What is thinning?","wrong_answer":"Replacing seeds that failed","correct_answer":"Removing extra seedlings"}'::jsonb, 'Thinning and gapping are taught together and both change the number of plants.', 'Offer "Replacing seeds that failed" next to the right answer and ask the question again in a new situation.', 'Use the words: thin = make fewer; gap = fill a gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES.M_AG7_CP_GAP', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES', 'Says gapping is removing extra seedlings.', '{"question":"What is gapping?","wrong_answer":"Removing extra seedlings","correct_answer":"Replacing seeds that did not grow"}'::jsonb, 'The child swaps the two words learnt together.', 'Offer "Removing extra seedlings" next to the right answer and ask the question again in a new situation.', 'Point at an empty space in a row: "a gap" is filled by gapping.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES.M_AG7_CP_EARTH', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.CROP_PRACTICES', 'Thinks earthing-up means adding more seeds round the plant.', '{"question":"What is earthing-up?","wrong_answer":"Sowing more seeds near the plant","correct_answer":"Heaping soil round the base of the stems"}'::jsonb, 'The word "earth" makes the child think of planting.', 'Offer "Sowing more seeds near the plant" next to the right answer and ask the question again in a new context.', 'Show earthed-up potatoes and maize; ask what has been added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS.M_AG7_PS_LATEGAP', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS', 'Gaps a month after the crop came up.', '{"question":"When should gapping be done?","wrong_answer":"A month or more after germination","correct_answer":"Within about two weeks of germination"}'::jsonb, 'The child does not see that late seedlings are shaded and left behind.', 'Offer "A month or more after germination" next to the right answer and ask the question again in a new context.', 'Show a late-gapped plant, small beside its neighbours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS.M_AG7_PS_THINWEAK', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS', 'Pulls out the biggest seedlings when thinning.', '{"question":"Which seedlings are left when thinning?","wrong_answer":"The smallest","correct_answer":"The strongest and healthiest at the right spacing"}'::jsonb, 'The child thinks the big ones have had their share.', 'Offer "The smallest" next to the right answer and ask the question again in a new context.', 'Compare a big and a weak seedling side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS.M_AG7_PS_THINDRY', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS', 'Thins when the soil is dry and hard.', '{"question":"When is thinning best done?","wrong_answer":"When the soil is dry and hard","correct_answer":"When the soil is moist, so the seedlings left are not disturbed"}'::jsonb, 'The child does not think about the roots of the plants left behind.', 'Offer "When the soil is dry and hard" next to the right answer and ask the question again in a new context.', 'Pull a seedling from dry soil and from moist soil; look at its neighbours.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS.M_AG7_PS_DEEPWEED', 'AGRI.G7.FOOD_P.SELECTED_CROP_MANAGEMENT.PRACTICE_STEPS', 'Weeds deep and close to the crop with a jembe, cutting its roots.', '{"question":"How should weeds close to young maize be removed?","wrong_answer":"Dig deep with a jembe right next to the stem","correct_answer":"Pull them by hand or weed shallowly, not cutting the crop''s roots"}'::jsonb, 'The child thinks deep weeding gets all the weed out.', 'Offer "Dig deep with a jembe right next to the stem" next to the right answer and ask the question again in a new context.', 'Show cut maize roots after deep weeding close to the stem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS.M_AG7_AP_RAW', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS', 'Thinks raw milk straight from the cow is always the safest.', '{"question":"What should be done to milk before drinking?","wrong_answer":"Nothing, raw is safest","correct_answer":"Boil or pasteurise it"}'::jsonb, 'The child links fresh with pure and has not heard of germs in milk.', 'Offer "Nothing, raw is safest" next to the right answer and ask the question again in a new situation.', 'Explain that milk can carry germs from the animal and the hands; boiling kills them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS.M_AG7_AP_HANDS', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS', 'Skips washing hands and tools before handling food from animals.', '{"question":"What should be done before handling meat?","wrong_answer":"Nothing at all","correct_answer":"Wash hands and tools"}'::jsonb, 'The child thinks clean-looking hands are clean.', 'Offer "Nothing at all" next to the right answer and ask the question again in a new situation.', 'Recall hand washing from Grade 4: germs cannot be seen.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS.M_AG7_AP_COOL', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS', 'Leaves milk or eggs in the hot sun.', '{"question":"How should fresh milk be kept?","wrong_answer":"In the hot sun","correct_answer":"Cool and covered"}'::jsonb, 'The child does not link warmth with food going bad.', 'Offer "In the hot sun" next to the right answer and ask the question again in a new situation.', 'Leave a cup of milk in the sun and one in the shade for a morning; smell both.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS.M_AG7_AP_WASHEGG', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.ANIMAL_PRODUCTS', 'Washes eggs in water before storing them.', '{"question":"How should dirty eggs be cleaned before storing?","wrong_answer":"Soak and wash them in water","correct_answer":"Wipe them with a dry cloth or rough paper"}'::jsonb, 'The child thinks washing always cleans best.', 'Offer "Soak and wash them in water" next to the right answer and ask the question again in a new context.', 'Explain the eggshell has tiny pores and a natural coat; water carries germs in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP.M_AG7_EH_GRADE', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP', 'Packs cracked and whole eggs together.', '{"question":"What is done with cracked eggs when grading?","wrong_answer":"Pack them with the others","correct_answer":"Remove them and use them first at home"}'::jsonb, 'The child sees a small crack as no problem.', 'Offer "Pack them with the others" next to the right answer and ask the question again in a new context.', 'Show how a cracked egg leaks and spoils the tray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP.M_AG7_EH_POINT', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP', 'Packs eggs in the tray pointed end up.', '{"question":"Which way up are eggs packed in a tray?","wrong_answer":"Pointed end up","correct_answer":"Broad end up"}'::jsonb, 'The child sets the egg as it looks neat.', 'Offer "Pointed end up" next to the right answer and ask the question again in a new context.', 'Candle an egg: the air space is at the broad end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP.M_AG7_EH_WATER', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP', 'Adds water to honey to make more of it.', '{"question":"Why must no water get into honey?","wrong_answer":"Water makes more honey to sell","correct_answer":"Watered honey ferments and goes sour"}'::jsonb, 'The child thinks of diluting juice.', 'Offer "Water makes more honey to sell" next to the right answer and ask the question again in a new context.', 'Explain honey keeps for years because it is very dry and thick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP.M_AG7_EH_OPEN', 'AGRI.G7.FOOD_P.PREPARING_ANIMAL_PRODUCT.EGG_HONEY_PREP', 'Stores honey in an open container.', '{"question":"How should strained honey be stored?","wrong_answer":"In an open basin","correct_answer":"In a clean, dry, airtight container, labelled"}'::jsonb, 'The child thinks honey cannot spoil at all.', 'Offer "In an open basin" next to the right answer and ask the question again in a new context.', 'Ask what comes to an open honey basin: ants, bees, dust, damp air.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG7_CK_STEAM', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Says steaming is cooking in oil.', '{"question":"What is steaming?","wrong_answer":"Cooking in oil","correct_answer":"Cooking over the steam of boiling water"}'::jsonb, 'The child mixes the cooking words because all four are taught together.', 'Offer "Cooking in oil" next to the right answer and ask the question again in a new situation.', 'Show steam rising from a pot; food in a basket above the water cooks in that steam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG7_CK_FRY', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Says frying is cooking in an oven.', '{"question":"What is frying?","wrong_answer":"Cooking in an oven","correct_answer":"Cooking in hot oil"}'::jsonb, 'The child pictures a hot box for all dry cooking.', 'Offer "Cooking in an oven" next to the right answer and ask the question again in a new situation.', 'Frying uses hot oil in a pan; an oven is for baking and roasting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG7_CK_BAKE', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Says boiling is the method that uses an oven.', '{"question":"Which method uses an oven?","wrong_answer":"Boiling","correct_answer":"Baking"}'::jsonb, 'The child guesses the most common cooking word.', 'Offer "Boiling" next to the right answer and ask the question again in a new situation.', 'Match each method to its heat: water (boiling), steam (steaming), oil (frying), oven (baking).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG7_CK_GRILL', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks grilling and roasting are the same as frying because the food browns.', '{"question":"How is grilling different from frying?","wrong_answer":"There is no difference; both brown the food","correct_answer":"Grilling cooks with direct dry heat and no oil; frying cooks in hot oil"}'::jsonb, 'The child judges by the brown colour of the food.', 'Offer "There is no difference; both brown the food" next to the right answer and ask the question again in a new context.', 'Show meat on a wire grill over charcoal and in a frying pan.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG7_CPR_DRY', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Lets the water in the steamer boil dry.', '{"question":"What must you watch when steaming food?","wrong_answer":"Nothing, steaming looks after itself","correct_answer":"That the water does not boil dry; top it up with boiling water"}'::jsonb, 'The child does not see the water under the food.', 'Offer "Nothing, steaming looks after itself" next to the right answer and ask the question again in a new context.', 'Show a steamer pan burnt dry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG7_CPR_TURN', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Leaves food on the grill without turning it.', '{"question":"Why is grilled meat turned?","wrong_answer":"It is not needed","correct_answer":"So both sides cook evenly and it does not burn"}'::jsonb, 'The child thinks heat reaches all sides.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Grill a tomato half without turning: burnt underneath, raw on top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG7_CPR_RAW', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Judges grilled chicken cooked because the outside is brown.', '{"question":"How do you know grilled chicken is cooked through?","wrong_answer":"The outside is brown","correct_answer":"The juices run clear and the inside is no longer pink"}'::jsonb, 'The child judges by the outside only.', 'Offer "The outside is brown" next to the right answer and ask the question again in a new context.', 'Cut a piece browned outside but pink inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE.M_AG7_CPR_SLEEVE', 'AGRI.G7.FOOD_P.COOKING_FOOD.COOKING_PRACTICE', 'Leans over the grill with loose sleeves and long hair untied.', '{"question":"How should you dress when grilling over a fire?","wrong_answer":"Any clothes are fine","correct_answer":"Sleeves rolled up, hair tied back, an apron on"}'::jsonb, 'The child does not think about clothes catching fire.', 'Offer "Any clothes are fine" next to the right answer and ask the question again in a new context.', 'Show how a loose sleeve hangs into a flame in a picture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE.M_AG7_AH_DUNG', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE', 'Leaves dung in the animal house because the animals do not mind it.', '{"question":"What should be done to the animals'' house?","wrong_answer":"Leave the dung inside","correct_answer":"Clean it and remove the dung"}'::jsonb, 'The child thinks animals live with dirt naturally.', 'Offer "Leave the dung inside" next to the right answer and ask the question again in a new situation.', 'Ask what grows in wet dung: flies, worms, germs that make animals sick.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE.M_AG7_AH_WATER', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE', 'Gives animals dirty water because animals drink from puddles anyway.', '{"question":"What water should animals drink?","wrong_answer":"Any dirty water","correct_answer":"Clean water"}'::jsonb, 'The child has seen animals drink from puddles and thinks they need no clean water.', 'Offer "Any dirty water" next to the right answer and ask the question again in a new situation.', 'Show a dirty waterer with green slime; animals catch diseases from it as people do.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE.M_AG7_AH_SICK', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE', 'Keeps a sick animal with the healthy ones.', '{"question":"What should be done with a sick animal?","wrong_answer":"Keep it with the others","correct_answer":"Separate it from the others"}'::jsonb, 'The child thinks the animal will feel lonely or that illness does not spread among animals.', 'Offer "Keep it with the others" next to the right answer and ask the question again in a new situation.', 'Ask how a cold spreads in a classroom; disease spreads the same way among animals.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE.M_AG7_AH_AIR', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.ANIMAL_HYGIENE', 'Closes up the animal house completely to keep it warm.', '{"question":"Why does an animal house need ventilation?","wrong_answer":"It does not; closed is warmer","correct_answer":"Fresh air removes damp and smells that cause disease"}'::jsonb, 'The child thinks warmth is all an animal needs.', 'Offer "It does not; closed is warmer" next to the right answer and ask the question again in a new context.', 'Compare the smell of a closed and an airy hen house.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING.M_AG7_HC_WETBED', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING', 'Puts fresh bedding on a floor that is still wet.', '{"question":"When is new bedding put in an animal house after cleaning?","wrong_answer":"Straight after scrubbing, while wet","correct_answer":"After the house has dried"}'::jsonb, 'The child wants to finish quickly.', 'Offer "Straight after scrubbing, while wet" next to the right answer and ask the question again in a new context.', 'Leave bedding on a wet floor overnight and smell it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING.M_AG7_HC_FEEDER', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING', 'Tops up feeders and waterers without washing them.', '{"question":"How often should a waterer be washed?","wrong_answer":"Never, only topped up","correct_answer":"Every day before refilling"}'::jsonb, 'The child sees the water level, not the slime.', 'Offer "Never, only topped up" next to the right answer and ask the question again in a new context.', 'Feel the inside of an unwashed waterer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING.M_AG7_HC_NOGLOVES', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING', 'Cleans out droppings with bare hands and no mask.', '{"question":"What should you wear to clean a poultry house?","wrong_answer":"Nothing special","correct_answer":"Gloves, a mask, an apron and gumboots"}'::jsonb, 'The child does not see dust and droppings as a danger.', 'Offer "Nothing special" next to the right answer and ask the question again in a new context.', 'Show the dust rising when bedding is moved.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING.M_AG7_HC_ORDER', 'AGRI.G7.HYGIEN.HYGIENE_IN_REARING_ANIMA.HOUSE_CLEANING', 'Disinfects before removing the old bedding and droppings.', '{"question":"What is done before using disinfectant in an animal house?","wrong_answer":"Nothing, spray it straight away","correct_answer":"Remove the bedding and droppings and scrub the house"}'::jsonb, 'The child thinks the disinfectant does all the work.', 'Offer "Nothing, spray it straight away" next to the right answer and ask the question again in a new context.', 'Explain disinfectant cannot reach germs under dirt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS.M_AG7_LC_WHITE', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS', 'Washes a loose-coloured shirt together with white clothes.', '{"question":"How should a loose-coloured shirt be washed?","wrong_answer":"With white clothes","correct_answer":"Separately"}'::jsonb, 'The child wants to save water and soap and has not seen colour run.', 'Offer "With white clothes" next to the right answer and ask the question again in a new situation.', 'Wash a scrap of loose-coloured cloth with a white handkerchief and show the stain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS.M_AG7_LC_SOAK', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS', 'Soaks a loose-coloured article for a whole day.', '{"question":"How long should a loose-coloured shirt be soaked?","wrong_answer":"For a whole day","correct_answer":"Not for long"}'::jsonb, 'The child soaks all clothes the same way to loosen dirt.', 'Offer "For a whole day" next to the right answer and ask the question again in a new situation.', 'Soak a loose-coloured scrap and watch the water change colour over an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS.M_AG7_LC_DRY', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS', 'Dries loose-coloured clothes in the hot sun.', '{"question":"Where should loose-coloured clothes dry?","wrong_answer":"In the hot sun","correct_answer":"In the shade"}'::jsonb, 'The child dries everything the same way and has seen whites dried in sun.', 'Offer "In the hot sun" next to the right answer and ask the question again in a new situation.', 'Recall Grade 5: colours dry inside out in the shade so they do not fade.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS.M_AG7_LC_MEANING', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.LAUNDRY_COLOURS', 'Thinks a loose-coloured article is one with a loose fit.', '{"question":"What is a loose-coloured article?","wrong_answer":"Clothing that fits loosely","correct_answer":"One whose dye comes out in water"}'::jsonb, 'The child takes "loose" from how clothes fit.', 'Offer "Clothing that fits loosely" next to the right answer and ask the question again in a new context.', 'Dip a corner of a loose-coloured scrap in water and press it on white paper.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS.M_AG7_CS_NOTEST', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS', 'Washes a new coloured item without testing whether the colour runs.', '{"question":"How can you test if a colour will run?","wrong_answer":"There is no way to know","correct_answer":"Press a damp white cloth on a hidden part; see if colour comes off"}'::jsonb, 'The child has not seen a colour test.', 'Offer "There is no way to know" next to the right answer and ask the question again in a new context.', 'Do the test on a hidden seam in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS.M_AG7_CS_HOT', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS', 'Washes loose colours in hot water to get them cleaner.', '{"question":"Which water is used for loose colours?","wrong_answer":"Hot water","correct_answer":"Cool or lukewarm water"}'::jsonb, 'The child thinks hotter water always cleans better.', 'Offer "Hot water" next to the right answer and ask the question again in a new context.', 'Dip loose-coloured scraps in hot and cool water; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS.M_AG7_CS_RUB', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS', 'Rubs and scrubs loose colours hard on a stone or board.', '{"question":"How is a loose-coloured article washed?","wrong_answer":"Scrubbed hard on a board","correct_answer":"Quickly, by kneading and squeezing"}'::jsonb, 'The child washes as for dirty work clothes.', 'Offer "Scrubbed hard on a board" next to the right answer and ask the question again in a new context.', 'Scrub a loose-coloured scrap and knead another; compare the colour left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS.M_AG7_CS_FOLDWET', 'AGRI.G7.HYGIEN.LAUNDRY_LOOSE_COLOURED_I.COLOUR_STEPS', 'Folds the wet article and leaves it in a heap.', '{"question":"What happens if a wet loose-coloured shirt is left folded in a basin?","wrong_answer":"Nothing","correct_answer":"The colour runs into the other parts of the shirt"}'::jsonb, 'The child does not think colour moves while the cloth is wet.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Leave a wet folded scrap for an hour and open it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING.M_AG7_KN_TOOL', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING', 'Names a hammer, nails or a crochet hook as the tools for knitting.', '{"question":"Which tools are used for knitting?","wrong_answer":"A hammer and nails","correct_answer":"Needles and yarn"}'::jsonb, 'The child mixes knitting with other making activities, or with crochet from Grade 6.', 'Offer "A hammer and nails" next to the right answer and ask the question again in a new situation.', 'Show a pair of knitting needles beside a crochet hook: knitting uses two needles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING.M_AG7_KN_STITCH', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING', 'Picks a made-up stitch such as "brick stitch" as a knitting stitch and rejects purl.', '{"question":"Which is a knitting stitch?","wrong_answer":"Brick stitch","correct_answer":"Purl stitch"}'::jsonb, 'The child does not yet know knit and purl are the two basic knitting stitches.', 'Offer "Brick stitch" next to the right answer and ask the question again in a new situation.', 'Knit one row and purl the next on a sample; name each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING.M_AG7_KN_CAST', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING', 'Says casting on is finishing the knitting.', '{"question":"What is casting on?","wrong_answer":"Finishing the knitting","correct_answer":"Making the first row of stitches"}'::jsonb, 'Casting on and casting off sound alike.', 'Offer "Finishing the knitting" next to the right answer and ask the question again in a new situation.', 'On starts the work (stitches go on the needle); off finishes it (stitches come off).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING.M_AG7_KN_GARTER', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNITTING', 'Thinks garter stitch is made by alternating knit and purl rows.', '{"question":"How is garter stitch made?","wrong_answer":"Knit one row, purl the next","correct_answer":"Knit every row"}'::jsonb, 'The child mixes the two basic patterns.', 'Offer "Knit one row, purl the next" next to the right answer and ask the question again in a new context.', 'Knit two samples: every row knit, and alternate rows; compare both faces.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE.M_AG7_KA_DROP', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE', 'Ignores a dropped stitch and keeps knitting.', '{"question":"A stitch has slipped off the needle. What happens if you ignore it?","wrong_answer":"Nothing","correct_answer":"It runs down and leaves a ladder or hole"}'::jsonb, 'The child does not see that each stitch holds the ones below.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Pull a dropped stitch on a sample and watch it run.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE.M_AG7_KA_TIGHT', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE', 'Casts on very tightly so the stitches will not slide.', '{"question":"Why should casting on not be too tight?","wrong_answer":"Tight is stronger","correct_answer":"The needle cannot go into the stitches and the edge will not stretch"}'::jsonb, 'The child thinks tight means strong.', 'Offer "Tight is stronger" next to the right answer and ask the question again in a new context.', 'Try to knit into a very tight cast-on row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE.M_AG7_KA_ENDS', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE', 'Cuts the yarn ends short and leaves them loose.', '{"question":"What is done with the yarn ends after casting off?","wrong_answer":"Cut them short and leave them","correct_answer":"Sew them in along the edge"}'::jsonb, 'The child thinks cutting the end finishes the article.', 'Offer "Cut them short and leave them" next to the right answer and ask the question again in a new context.', 'Wash a sample with loose short ends; it starts to unravel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE.M_AG7_KA_COUNT', 'AGRI.G7.PRODUC.KNITTING_SKILLS.KNIT_ARTICLE', 'Casts on without counting, so the mat is the wrong width.', '{"question":"How do you make a knitted mat the right width?","wrong_answer":"Cast on until it looks wide enough","correct_answer":"Knit a small test square, measure it and cast on the number needed"}'::jsonb, 'The child judges by eye.', 'Offer "Cast on until it looks wide enough" next to the right answer and ask the question again in a new context.', 'Measure a 10-stitch test square and work out the stitches for 30 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN.M_AG7_FG_SPACE', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN', 'Thinks a framed suspended garden needs a big field.', '{"question":"Why use a suspended garden?","wrong_answer":"It needs a big field","correct_answer":"It saves space"}'::jsonb, 'The child links any garden with a field.', 'Offer "It needs a big field" next to the right answer and ask the question again in a new situation.', 'Show a frame on a veranda or beside a wall growing kale in bottles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN.M_AG7_FG_DRAIN', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN', 'Leaves the hanging containers with no drainage holes.', '{"question":"What must the containers have?","wrong_answer":"No holes at all","correct_answer":"Holes for drainage"}'::jsonb, 'The child thinks holes waste water.', 'Offer "No holes at all" next to the right answer and ask the question again in a new situation.', 'Water a container with no holes for a week; the roots rot in standing water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN.M_AG7_FG_SOIL', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN', 'Fills the containers with sand only.', '{"question":"What should the soil mixture have?","wrong_answer":"Only sand","correct_answer":"Soil and manure"}'::jsonb, 'The child thinks sand drains well and so is best.', 'Offer "Only sand" next to the right answer and ask the question again in a new situation.', 'Compare kale in sand only and in soil with manure after three weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN.M_AG7_FG_CROP', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAMED_GARDEN', 'Thinks tall heavy crops like maize or bananas suit a suspended garden.', '{"question":"Which crop suits a framed suspended garden?","wrong_answer":"Maize or bananas","correct_answer":"Kale, spinach, strawberries or herbs"}'::jsonb, 'The child thinks any crop grows in any garden.', 'Offer "Maize or bananas" next to the right answer and ask the question again in a new context.', 'Ask how heavy a banana bunch is compared with a bottle of soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD.M_AG7_FB_WEAK', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD', 'Uses thin sticks that bend under the weight of soil and water.', '{"question":"Why must the frame be strong?","wrong_answer":"It does not carry much","correct_answer":"Wet soil in many containers is heavy"}'::jsonb, 'The child does not picture the weight of wet soil.', 'Offer "It does not carry much" next to the right answer and ask the question again in a new context.', 'Weigh a bottle of dry soil and of wet soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD.M_AG7_FB_SHADE', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD', 'Hangs the rows so close that the top containers shade the lower ones.', '{"question":"How should the rows of containers be hung?","wrong_answer":"As close together as possible","correct_answer":"Spaced or staggered so every plant gets light"}'::jsonb, 'The child wants to fit in as many as possible.', 'Offer "As close together as possible" next to the right answer and ask the question again in a new context.', 'Hang two rows close together and look at the shadow on the lower row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD.M_AG7_FB_POSTS', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD', 'Stands the uprights on the ground without fixing them.', '{"question":"How are the uprights of the frame fixed?","wrong_answer":"Stood on the ground","correct_answer":"Dug into the ground or braced firmly"}'::jsonb, 'The child thinks the weight holds the frame down.', 'Offer "Stood on the ground" next to the right answer and ask the question again in a new context.', 'Push a free-standing model frame with wet bottles on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD.M_AG7_FB_NOPLAN', 'AGRI.G7.PRODUC.CONSTRUCTING_FRAMED_SUSP.FRAME_BUILD', 'Starts cutting and joining without a sketch or measurements.', '{"question":"What is done before cutting the materials?","wrong_answer":"Nothing, start building","correct_answer":"Sketch the frame and measure"}'::jsonb, 'The child is keen to build.', 'Offer "Nothing, start building" next to the right answer and ask the question again in a new context.', 'Show pieces cut too short for the frame.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION.M_AG7_VA_RAW', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION', 'Thinks raw produce always sells for more than processed produce.', '{"question":"How does value addition help a farmer?","wrong_answer":"It lowers the price","correct_answer":"It raises the selling price"}'::jsonb, 'The child thinks fresh is always worth most.', 'Offer "It lowers the price" next to the right answer and ask the question again in a new situation.', 'Compare the price of a kilogram of raw groundnuts with roasted, packed groundnuts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION.M_AG7_VA_EXAMPLE', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION', 'Gives leaving produce to rot or selling it unsorted as value addition.', '{"question":"Which is value addition?","wrong_answer":"Leaving mangoes to rot","correct_answer":"Making mangoes into juice"}'::jsonb, 'The child does not know what "value" means in selling.', 'Offer "Leaving mangoes to rot" next to the right answer and ask the question again in a new situation.', 'Define value addition: changing produce so it is worth more or keeps longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION.M_AG7_VA_STEPS', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION', 'Skips cleaning and sorting before processing.', '{"question":"What comes first in preparing produce for sale?","wrong_answer":"Selling it dirty","correct_answer":"Cleaning and sorting"}'::jsonb, 'The child goes straight to the interesting part: drying or frying.', 'Offer "Selling it dirty" next to the right answer and ask the question again in a new situation.', 'Show crisps made from unsorted potatoes with bad spots; who would buy them?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION.M_AG7_VA_LIFE', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_ADDITION', 'Thinks value addition is only about price and not about keeping produce longer.', '{"question":"How else does drying cassava add value, besides a better price?","wrong_answer":"It does not; price is all","correct_answer":"It keeps for months instead of days"}'::jsonb, 'The child thinks of value as money only.', 'Offer "It does not; price is all" next to the right answer and ask the question again in a new context.', 'Compare a raw cassava root after a week with dried chips.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS.M_AG7_VS_PACK', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS', 'Packs dried chips while still warm or in an open bag.', '{"question":"How are dried chips packed?","wrong_answer":"Warm, in an open bag","correct_answer":"Cooled, in a clean sealed packet, labelled"}'::jsonb, 'The child thinks drying is the last step.', 'Offer "Warm, in an open bag" next to the right answer and ask the question again in a new context.', 'Pack warm chips in a sealed bag: droplets form inside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS.M_AG7_VS_THICK', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS', 'Slices the produce in thick, uneven pieces.', '{"question":"Why are potatoes sliced thin and even for crisps?","wrong_answer":"It does not matter","correct_answer":"So they cook or dry evenly and are crisp"}'::jsonb, 'The child thinks only taste matters.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Fry or dry thick and thin slices; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS.M_AG7_VS_LABEL', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS', 'Thinks a label is just decoration.', '{"question":"Why is a packet of dried pumpkin labelled?","wrong_answer":"Only to look nice","correct_answer":"To tell the buyer what it is, its weight, the date and who made it"}'::jsonb, 'The child has not thought about what a buyer needs to know.', 'Offer "Only to look nice" next to the right answer and ask the question again in a new context.', 'Compare two packets, one labelled and one plain; which would you buy?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS.M_AG7_VS_SPOILT', 'AGRI.G7.PRODUC.ADDING_VALUE_TO_CROP_PRO.VALUE_STEPS', 'Uses produce with rotten or bitter parts to save money.', '{"question":"Can sweet potatoes with rotten spots be used for chips?","wrong_answer":"Yes, it saves money","correct_answer":"No, sort them out; rot spoils the taste and the whole batch"}'::jsonb, 'The child does not want to waste anything.', 'Offer "Yes, it saves money" next to the right answer and ask the question again in a new context.', 'Show chips with dark bitter spots.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS.M_AG7_SF_FORM', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS', 'Names a non-soap such as a brick or stone as a form of soap.', '{"question":"Which is a form of soap?","wrong_answer":"Brick","correct_answer":"Bar"}'::jsonb, 'The child takes "bar" to mean any hard block.', 'Offer "Brick" next to the right answer and ask the question again in a new situation.', 'Show bar, liquid, paste and powder soap side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS.M_AG7_SF_USE', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS', 'Thinks soap cleans without water.', '{"question":"What does soap do with water?","wrong_answer":"Adds dirt","correct_answer":"Removes dirt and germs"}'::jsonb, 'The child sees soap as the cleaner and water as optional.', 'Offer "Adds dirt" next to the right answer and ask the question again in a new situation.', 'Rub dry soap on a dirty cloth and then with water; only the wet one lathers and lifts dirt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS.M_AG7_SF_SAFE', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS', 'Thinks children may handle the strong ingredients of soap alone.', '{"question":"Who handles strong soap chemicals?","wrong_answer":"Any child alone","correct_answer":"The teacher only"}'::jsonb, 'The child does not know lye from ashes or caustic soda burns skin and eyes.', 'Offer "Any child alone" next to the right answer and ask the question again in a new situation.', 'Read a caustic soda warning label; only the teacher handles lye, with gloves and goggles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS.M_AG7_SF_POWDER', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_FORMS', 'Thinks powder soap is only for clothes and bar soap only for bathing, so no form has another use.', '{"question":"Which form of soap is often used for washing dishes?","wrong_answer":"Only bar soap for bathing","correct_answer":"Liquid or paste soap"}'::jsonb, 'The child knows each form from one use at home.', 'Offer "Only bar soap for bathing" next to the right answer and ask the question again in a new context.', 'List where each form is used at home and at school.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING.M_AG7_SM_FAT', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING', 'Thinks soap is made from ash and water alone.', '{"question":"Which ingredient is mixed with lye from ashes to make soap?","wrong_answer":"Nothing else is needed","correct_answer":"Animal fat or plant oil"}'::jsonb, 'The child has heard ash cleans pots and thinks it is the soap.', 'Offer "Nothing else is needed" next to the right answer and ask the question again in a new context.', 'Show the ingredients list: lye plus fat or oil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING.M_AG7_SM_CURE', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING', 'Uses the soap the day it is poured into the mould.', '{"question":"When is homemade soap ready to use?","wrong_answer":"As soon as it is poured","correct_answer":"After it has hardened and cured for some weeks"}'::jsonb, 'The child thinks soap is ready once it is made.', 'Offer "As soon as it is poured" next to the right answer and ask the question again in a new context.', 'Explain fresh soap is still harsh; curing makes it mild and hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING.M_AG7_SM_POT', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING', 'Thinks any cooking pot can be used for soap and then for food again.', '{"question":"Can the soap-making pot be used for cooking afterwards?","wrong_answer":"Yes, after a rinse","correct_answer":"No, keep a separate pot for soap making"}'::jsonb, 'The child does not think lye stays in the pot.', 'Offer "Yes, after a rinse" next to the right answer and ask the question again in a new context.', 'Ask what could be left on the pot''s surface.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING.M_AG7_SM_SALT', 'AGRI.G7.PRODUC.MAKING_HOMEMADE_SOAP.SOAP_MAKING', 'Thinks salt is added to soap for flavour.', '{"question":"Why is salt added in homemade soap making?","wrong_answer":"For taste","correct_answer":"To help the soap separate and set hard"}'::jsonb, 'The child links salt with food.', 'Offer "For taste" next to the right answer and ask the question again in a new context.', 'Show soap made with and without salt: one stays soft.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
